BEGIN;
CREATE TABLE mathchakchak.privacy_external_reference_proof_release_decision_contract(id uuid PRIMARY KEY,scan_attestation_contract_id uuid NOT NULL REFERENCES mathchakchak.privacy_external_reference_proof_scan_attestation_contract(id) ON DELETE RESTRICT,package_manifest_id uuid NOT NULL REFERENCES mathchakchak.privacy_fulfilment_package_manifest(id) ON DELETE RESTRICT,revision integer NOT NULL CHECK(revision>0),predecessor_contract_id uuid REFERENCES mathchakchak.privacy_external_reference_proof_release_decision_contract(id) ON DELETE RESTRICT,schema_version varchar(16) NOT NULL CHECK(schema_version='1.0.0'),status varchar(64) NOT NULL CHECK(status='RELEASE_DECISION_POLICY_ONLY_REVIEWERS_MISSING'),contract_manifest jsonb NOT NULL,contract_sha256 char(64) NOT NULL CHECK(contract_sha256~'^[0-9a-f]{64}$'),created_by_user_id uuid NOT NULL REFERENCES mathchakchak.app_user(id) ON DELETE RESTRICT,kill_switch_engaged boolean NOT NULL DEFAULT true CHECK(kill_switch_engaged=true),reviewer_assignment_authorized boolean NOT NULL DEFAULT false CHECK(reviewer_assignment_authorized=false),decision_write_authorized boolean NOT NULL DEFAULT false CHECK(decision_write_authorized=false),quarantine_release_authorized boolean NOT NULL DEFAULT false CHECK(quarantine_release_authorized=false),execution_authorized boolean NOT NULL DEFAULT false CHECK(execution_authorized=false),created_at timestamptz NOT NULL DEFAULT now(),CHECK((revision=1 AND predecessor_contract_id IS NULL)OR(revision>1 AND predecessor_contract_id IS NOT NULL)),UNIQUE(scan_attestation_contract_id,revision),UNIQUE(predecessor_contract_id));
CREATE TABLE mathchakchak.privacy_external_reference_proof_release_decision_requirement(id uuid PRIMARY KEY,release_contract_id uuid NOT NULL REFERENCES mathchakchak.privacy_external_reference_proof_release_decision_contract(id) ON DELETE RESTRICT,control_key varchar(48) NOT NULL,owner_role varchar(48) NOT NULL,decision_fields jsonb NOT NULL CHECK(jsonb_array_length(decision_fields)=12),decision_enums jsonb NOT NULL CHECK(jsonb_array_length(decision_enums)=3),review_checks jsonb NOT NULL CHECK(jsonb_array_length(review_checks)=10),rejection_reasons jsonb NOT NULL CHECK(jsonb_array_length(rejection_reasons)=10),segregation_controls jsonb NOT NULL CHECK(jsonb_array_length(segregation_controls)=6),assigned_reviewers jsonb NOT NULL CHECK(assigned_reviewers='[]'::jsonb),recorded_decisions jsonb NOT NULL CHECK(recorded_decisions='[]'::jsonb),readiness_status varchar(64) NOT NULL CHECK(readiness_status='POLICY_DEFINED_REVIEWERS_AND_RESULTS_MISSING'),reviewer_status varchar(24) NOT NULL DEFAULT 'MISSING_EXTERNAL' CHECK(reviewer_status='MISSING_EXTERNAL'),result_status varchar(24) NOT NULL DEFAULT 'MISSING_EXTERNAL' CHECK(result_status='MISSING_EXTERNAL'),decision_status varchar(24) NOT NULL DEFAULT 'NOT_STARTED' CHECK(decision_status='NOT_STARTED'),metadata_only boolean NOT NULL DEFAULT true CHECK(metadata_only=true),fail_closed boolean NOT NULL DEFAULT true CHECK(fail_closed=true),human_review_required boolean NOT NULL DEFAULT true CHECK(human_review_required=true),conflict_declaration_required boolean NOT NULL DEFAULT true CHECK(conflict_declaration_required=true),raw_evidence_storage_allowed boolean NOT NULL DEFAULT false CHECK(raw_evidence_storage_allowed=false),reviewer_identity_reference varchar(191),contact_reference varchar(191),conflict_declaration varchar(48),decision_reference varchar(191),decision varchar(48),reason_code varchar(96),assigned_at timestamptz,acknowledged_at timestamptz,decided_at timestamptz,reviewer_assignment_write_allowed boolean NOT NULL DEFAULT false CHECK(reviewer_assignment_write_allowed=false),acknowledgement_write_allowed boolean NOT NULL DEFAULT false CHECK(acknowledgement_write_allowed=false),decision_write_allowed boolean NOT NULL DEFAULT false CHECK(decision_write_allowed=false),deletion_request_write_allowed boolean NOT NULL DEFAULT false CHECK(deletion_request_write_allowed=false),quarantine_release_allowed boolean NOT NULL DEFAULT false CHECK(quarantine_release_allowed=false),automatic_promotion_allowed boolean NOT NULL DEFAULT false CHECK(automatic_promotion_allowed=false),CHECK(reviewer_identity_reference IS NULL AND contact_reference IS NULL AND conflict_declaration IS NULL AND decision_reference IS NULL AND decision IS NULL AND reason_code IS NULL AND assigned_at IS NULL AND acknowledged_at IS NULL AND decided_at IS NULL),UNIQUE(release_contract_id,control_key));
CREATE OR REPLACE FUNCTION mathchakchak.reject_proof_release_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'EXTERNAL_REFERENCE_PROOF_RELEASE_APPEND_ONLY'; END; $$;
CREATE TRIGGER proof_release_contract_immutable BEFORE UPDATE OR DELETE ON mathchakchak.privacy_external_reference_proof_release_decision_contract FOR EACH ROW EXECUTE FUNCTION mathchakchak.reject_proof_release_mutation();
CREATE TRIGGER proof_release_requirement_immutable BEFORE UPDATE OR DELETE ON mathchakchak.privacy_external_reference_proof_release_decision_requirement FOR EACH ROW EXECUTE FUNCTION mathchakchak.reject_proof_release_mutation();
CREATE INDEX proof_release_attestation_idx ON mathchakchak.privacy_external_reference_proof_release_decision_contract(scan_attestation_contract_id,revision DESC);
COMMIT;
